-- 0026_research_claims_and_evidence.sql
-- Phase 3 research persistence: claims, claim_sources, evidence_assessments.
-- Imports cited blocks from published.json only. Does not split summary paragraphs.
-- Does not create regulatory_records or community_reports. Lexicon still reads files.

create table public.claims (
  id uuid primary key default gen_random_uuid(),
  stable_key text not null,
  substance_id uuid not null references public.substances (id) on delete restrict,
  claim_type text not null
    check (claim_type in (
      'mechanism', 'effect', 'efficacy', 'safety',
      'pharmacology', 'clinical_evidence', 'current_research', 'other'
    )),
  statement text not null check (char_length(trim(statement)) >= 1),
  status text not null
    check (status in ('draft', 'review-required', 'approved', 'rejected')),
  safety_category text
    check (safety_category is null or safety_category in (
      'common_adverse_event', 'serious_adverse_event', 'warning',
      'contraindication', 'long_term_unknown', 'interaction'
    )),
  supersedes_claim_id uuid references public.claims (id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.claims is
  'One published scientific statement. status is workflow, not evidence A–F. Community claims are not stored.';
comment on column public.claims.stable_key is
  'Stable identity independent of statement text (substance slug + published slot).';
comment on column public.claims.supersedes_claim_id is
  'Reserved for later claim versioning. Unused in Phase 3 import.';

create unique index claims_stable_key_key on public.claims (stable_key);
create index claims_substance_status_idx on public.claims (substance_id, status);
create index claims_claim_type_idx on public.claims (claim_type);

create trigger claims_set_updated_at
  before update on public.claims
  for each row execute function public.set_updated_at();

create table public.claim_sources (
  id uuid primary key default gen_random_uuid(),
  claim_id uuid not null references public.claims (id) on delete restrict,
  source_id uuid not null references public.sources (id) on delete restrict,
  study_id uuid references public.studies (id) on delete restrict,
  created_at timestamptz not null default now(),
  constraint claim_sources_pair unique (claim_id, source_id)
);

comment on table public.claim_sources is
  'Claim ↔ source. Optional study_id when the cited source has an NCT.';

create index claim_sources_source_id_idx on public.claim_sources (source_id);
create index claim_sources_study_id_idx on public.claim_sources (study_id);

create table public.evidence_assessments (
  id uuid primary key default gen_random_uuid(),
  claim_id uuid not null references public.claims (id) on delete restrict,
  evidence_level text
    check (evidence_level is null or evidence_level in ('A', 'B', 'C', 'D', 'E', 'F')),
  confidence text
    check (confidence is null or confidence in ('high', 'moderate', 'low', 'insufficient')),
  evidence_type text not null
    check (evidence_type in (
      'human', 'clinical_trial', 'observational', 'case_report',
      'systematic_review', 'meta_analysis', 'animal', 'in_vitro',
      'mechanistic', 'regulatory', 'other'
    )),
  rationale text,
  review_status text not null
    check (review_status in ('draft', 'review-required', 'approved', 'rejected')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint evidence_assessments_claim_key unique (claim_id),
  constraint evidence_assessments_no_community_type check (
    evidence_type not in ('community', 'anecdotal', 'blog', 'reddit')
  )
);

comment on table public.evidence_assessments is
  'Claim-level evidence. A–F is not copied onto every claim; only published overlay humanEvidence carries substance-level A–F. Community cannot appear here.';

create index evidence_assessments_level_idx on public.evidence_assessments (evidence_level);
create index evidence_assessments_review_status_idx on public.evidence_assessments (review_status);

create trigger evidence_assessments_set_updated_at
  before update on public.evidence_assessments
  for each row execute function public.set_updated_at();

alter table public.claims enable row level security;
alter table public.claim_sources enable row level security;
alter table public.evidence_assessments enable row level security;

create policy "claims_select_authenticated"
  on public.claims for select to authenticated
  using (auth.uid() is not null and (status = 'approved' or public.has_role(auth.uid(), 'admin')));

create policy "claims_write_admin"
  on public.claims for insert to authenticated
  with check (public.has_role(auth.uid(), 'admin'));

create policy "claims_update_admin"
  on public.claims for update to authenticated
  using (public.has_role(auth.uid(), 'admin'))
  with check (public.has_role(auth.uid(), 'admin'));

create policy "claims_delete_admin"
  on public.claims for delete to authenticated
  using (public.has_role(auth.uid(), 'admin'));

create policy "claim_sources_select_authenticated"
  on public.claim_sources for select to authenticated
  using (
    auth.uid() is not null and (
      public.has_role(auth.uid(), 'admin')
      or exists (
        select 1 from public.claims c
        where c.id = claim_id and c.status = 'approved'
      )
    )
  );

create policy "claim_sources_write_admin"
  on public.claim_sources for insert to authenticated
  with check (public.has_role(auth.uid(), 'admin'));

create policy "claim_sources_update_admin"
  on public.claim_sources for update to authenticated
  using (public.has_role(auth.uid(), 'admin'))
  with check (public.has_role(auth.uid(), 'admin'));

create policy "claim_sources_delete_admin"
  on public.claim_sources for delete to authenticated
  using (public.has_role(auth.uid(), 'admin'));

create policy "evidence_assessments_select_authenticated"
  on public.evidence_assessments for select to authenticated
  using (
    auth.uid() is not null and (
      public.has_role(auth.uid(), 'admin')
      or exists (
        select 1 from public.claims c
        where c.id = claim_id and c.status = 'approved'
      )
    )
  );

create policy "evidence_assessments_write_admin"
  on public.evidence_assessments for insert to authenticated
  with check (public.has_role(auth.uid(), 'admin'));

create policy "evidence_assessments_update_admin"
  on public.evidence_assessments for update to authenticated
  using (public.has_role(auth.uid(), 'admin'))
  with check (public.has_role(auth.uid(), 'admin'));

create policy "evidence_assessments_delete_admin"
  on public.evidence_assessments for delete to authenticated
  using (public.has_role(auth.uid(), 'admin'));

grant select, insert, update, delete on public.claims to authenticated;
grant select, insert, update, delete on public.claim_sources to authenticated;
grant select, insert, update, delete on public.evidence_assessments to authenticated;
grant select, insert, update, delete on public.claims to service_role;
grant select, insert, update, delete on public.claim_sources to service_role;
grant select, insert, update, delete on public.evidence_assessments to service_role;

